scwin.grid1_ongroupby = function(options) {
	options.rowNumHeader = {
		inputType: 'expression',
		expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
		align: 'left',
		colSpan: 5
	};
	options.rowNumFooter = {
		colSpan: 3
	};
	options.rowStatusFooter = {
		value: '합계'
	};
	options.groupbyFooter = [{
		inputType: 'expression',
		expression: 'SUM("col3")'
	}];
	this.groupby(options);
	return false;
}
scwin.formatter = function(data) {
};
scwin.___fireOver = function(id) {
	var node = scwin.__getDom($p.id + id);
	if (document.createEventObject) {
		node.fireEvent('onmouseover');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('mouseover', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.onmouseover == 'function') {
		node.onmouseover();
	}
}
scwin.checkVal = function() {
	return typeof grid2_tooltip == "undefined";
}
